import type { Park } from '../types/park'
import { getAmenity } from './amenities.ts'

function searchableText(park: Park): string[] {
  const fields: string[] = []
  if (park.name !== null) fields.push(park.name)
  const address = park.location?.address ?? null
  if (address !== null) fields.push(address)
  for (const slug of park.amenities ?? []) fields.push(getAmenity(slug).label)
  return fields
}

export function filterParks(parks: Park[], query: string | null): Park[] {
  const needle = (query ?? '').trim().toLowerCase()
  if (needle === '') return parks
  return parks.filter((park) =>
    searchableText(park).some((text) => text.toLowerCase().includes(needle)),
  )
}

import { describe, expect, it } from 'vitest'
import type { Park } from '../types/park'
import { getParks } from '../data/parks'
import { filterParks } from './filterParks'

function park(overrides: Partial<Park> & { id: string }): Park {
  return {
    name: null,
    description: null,
    location: null,
    amenities: null,
    hours: null,
    images: null,
    acreage: null,
    rating: null,
    ...overrides,
  }
}

const RIVERSIDE = park({
  id: 'riverside',
  name: 'Riverside Commons',
  location: { lat: 1, lng: 1, address: '100 River Rd, Brooklyn, NY' },
  amenities: ['dog-run', 'bike-path'],
})
const PLAZA = park({
  id: 'plaza',
  name: 'Central Plaza Green',
  location: { lat: 2, lng: 2, address: '5 Main St, Queens, NY' },
  amenities: ['wifi', 'food-vendors'],
})
const NO_DETAILS = park({ id: 'bare' })
const NO_ADDRESS = park({
  id: 'no-address',
  name: 'Highland Dog Park',
  location: { lat: 3, lng: 3, address: null },
  amenities: [],
})

const PARKS = [RIVERSIDE, PLAZA, NO_DETAILS, NO_ADDRESS]

describe('filterParks', () => {
  it('returns every park for an empty, blank, or null query', () => {
    expect(filterParks(PARKS, '')).toBe(PARKS)
    expect(filterParks(PARKS, '   ')).toBe(PARKS)
    expect(filterParks(PARKS, null)).toBe(PARKS)
  })

  it('matches the name case-insensitively', () => {
    expect(filterParks(PARKS, 'riverSIDE')).toEqual([RIVERSIDE])
  })

  it('trims the query', () => {
    expect(filterParks(PARKS, '  plaza  ')).toEqual([PLAZA])
  })

  it('matches the address', () => {
    expect(filterParks(PARKS, 'queens')).toEqual([PLAZA])
    expect(filterParks(PARKS, ', ny')).toEqual([RIVERSIDE, PLAZA])
  })

  it('matches amenity labels, not slugs', () => {
    expect(filterParks(PARKS, 'wi-fi')).toEqual([PLAZA])
    expect(filterParks(PARKS, 'bike path')).toEqual([RIVERSIDE])
    expect(filterParks(PARKS, 'bike-path')).toEqual([])
  })

  it('matches the name of a park with no address', () => {
    expect(filterParks(PARKS, 'dog')).toEqual([RIVERSIDE, NO_ADDRESS])
  })

  it('returns an empty array when nothing matches', () => {
    expect(filterParks(PARKS, 'zzz-no-match')).toEqual([])
  })

  it('keeps the input order and does not mutate the input', () => {
    const input = [...PARKS]
    filterParks(input, 'park')
    expect(input).toEqual(PARKS)
  })

  it('works on the real data', () => {
    const all = getParks()
    expect(filterParks(all, '')).toHaveLength(all.length)
    expect(filterParks(all, 'prospect').map((p) => p.id)).toContain('prospect-park')
    expect(filterParks(all, 'highland').map((p) => p.id)).toContain('highland-dog-park')
  })
})

import { useId, type Ref } from 'react'
import { Search, X } from 'lucide-react'
import { joinClasses } from '../ui/joinClasses.ts'

type SearchInputProps = {
  value: string
  onChange: (value: string) => void
  label?: string
  placeholder?: string
  className?: string
  ref?: Ref<HTMLInputElement>
}

const focusRing =
  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2'

export function SearchInput({
  value,
  onChange,
  label = 'Search parks',
  placeholder = 'Name, address, or amenity',
  className,
  ref,
}: SearchInputProps) {
  const inputId = useId()

  return (
    <div className={joinClasses('flex flex-col gap-1', className)}>
      <label htmlFor={inputId} className="text-sm font-medium text-ink">
        {label}
      </label>
      <div className="relative">
        <Search
          aria-hidden="true"
          className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted"
        />
        <input
          ref={ref}
          id={inputId}
          type="search"
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Escape' && value !== '') {
              event.preventDefault()
              onChange('')
            }
          }}
          placeholder={placeholder}
          autoComplete="off"
          enterKeyHint="search"
          className={`w-full rounded-xl border border-slate-300 bg-surface py-2.5 pr-10 pl-9 text-base text-ink placeholder:text-muted [&::-webkit-search-cancel-button]:appearance-none ${focusRing}`}
        />
        {value !== '' && (
          <button
            type="button"
            onClick={(event) => {
              onChange('')
              event.currentTarget.closest('div')?.querySelector('input')?.focus()
            }}
            aria-label="Clear search"
            className={`absolute top-1/2 right-1.5 inline-flex size-8 -translate-y-1/2 items-center justify-center rounded-full text-muted hover:bg-chip hover:text-ink ${focusRing}`}
          >
            <X aria-hidden="true" className="size-4" />
          </button>
        )}
      </div>
    </div>
  )
}

